class LFUCache {
    int capacity;
    int minFreq;

    // key -> (value, frequency, iterator into freqMap[frequency] list)
    struct Node {
        int value;
        int freq;
        std::list<int>::iterator it; // points at this key inside its bucket list
    };
    std::unordered_map<int, Node> keyMap;

    // frequency -> doubly linked list of keys currently at that frequency,
    // front = most recently used, back = least recently used
    std::unordered_map<int, std::list<int>> freqMap;

public:
    LFUCache(int capacity) : capacity(capacity), minFreq(0) {}

    int get(int key) {
        if (keyMap.find(key) == keyMap.end()) return -1;
        touch(key);
        return keyMap[key].value;
    }

    void put(int key, int value) {
        if (capacity <= 0) return;

        if (keyMap.find(key) != keyMap.end()) {
            keyMap[key].value = value;
            touch(key);
            return;
        }

        if ((int)keyMap.size() >= capacity) {
            // evict the least recently used key from the minFreq bucket
            int evictKey = freqMap[minFreq].back();
            freqMap[minFreq].pop_back();
            keyMap.erase(evictKey);
        }

        // brand new key always starts at frequency 1
        freqMap[1].push_front(key);
        keyMap[key] = { value, 1, freqMap[1].begin() };
        minFreq = 1;
    }

private:
    void touch(int key) {
        Node& node = keyMap[key];
        int oldFreq = node.freq;

        // step 1: remove from old bucket
        freqMap[oldFreq].erase(node.it);

        // step 2: minFreq bookkeeping if the old bucket just emptied
        if (freqMap[oldFreq].empty()) {
            freqMap.erase(oldFreq);
            if (minFreq == oldFreq) minFreq++;
        }

        // step 3: bump the stored frequency
        node.freq++;

        // step 4: insert at the front of the new bucket
        freqMap[node.freq].push_front(key);
        node.it = freqMap[node.freq].begin();
    }
};
